SELECT (COUNT(CASE WHEN T1.height < 180 AND T2.overall_rating > 70 THEN 1 END) * 100.0 / COUNT(T1.id)) AS percentage
FROM Player AS T1
INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id;

